// Block (composition) — an overlapping group of people with compact overflow.
// Avatar owns the individual look; this Block only arranges the overlap.
import type { Ref } from "react";
import { Avatar } from "../components/Avatar";
import { Stack } from "../layouts/Stack";
import "./AvatarGroup.css";

export interface AvatarGroupProps {
  avatars: { src?: string; name: string }[];
  max?: number;
  className?: string;
  ref?: Ref<HTMLElement>;
}

const initials = (name: string) =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("") || "U";

export function AvatarGroup({ avatars, max = 4, className, ref }: AvatarGroupProps) {
  const visibleCount = Math.max(0, Math.floor(max));
  const visible = avatars.slice(0, visibleCount);
  const overflow = Math.max(avatars.length - visible.length, 0);

  return (
    <Stack
      ref={ref}
      direction="row"
      gap="none"
      align="center"
      role="group"
      aria-label={`${avatars.length} team members`}
      className={className ? `sd-avatargroup ${className}` : "sd-avatargroup"}
    >
      {/* spacing: bridged — each avatar overlaps the one before, so the overlap is the relationship */}
      {visible.map((avatar, index) => (
        <Avatar
          key={`${avatar.name}-${index}`}
          src={avatar.src}
          alt={avatar.name}
          size="small"
          data-overlap={index > 0 || undefined}
          className="sd-avatargroup__avatar"
        >
          {initials(avatar.name)}
        </Avatar>
      ))}
      {overflow > 0 && (
        <Avatar
          alt={`${overflow} more team members`}
          size="small"
          data-overlap={visible.length > 0 || undefined}
          className="sd-avatargroup__avatar"
        >
          +{overflow}
        </Avatar>
      )}
    </Stack>
  );
}

/* AvatarGroup.css — .sd-avatargroup (Block)
   Arrangement only: the negative margin is unique to the overlap composition. */
.sd-avatargroup {
  width: max-content;
}

.sd-avatargroup__avatar {
  flex-shrink: 0;
}

.sd-avatargroup__avatar[data-overlap] {
  margin-inline-start: calc(-1 * var(--sd-space-x-small));
}
